from docx import Document
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from pathlib import Path
import json,zlib,base64
D=json.loads(zlib.decompress(base64.b64decode("")).decode())
DOC=Path("รายงานสหกิจ.docx")
def fp(doc,x):
 for p in doc.paragraphs:
  if p.text.strip()==x:return p
 raise RuntimeError("anchor missing: "+x)
def db(a,b):
 n=a._p.getnext()
 while n is not None and n is not b._p:
  q=n.getnext(); n.getparent().remove(n); n=q
def ip(a,t="",s="Normal",bold=False,center=False):
 p=a.insert_paragraph_before(t,style=s)
 if center:p.alignment=WD_ALIGN_PARAGRAPH.CENTER
 if bold:
  for r in p.runs:r.bold=True
 return p
def sec(a,h,ps):
 ip(a,h,"Heading 1")
 for x in ps:ip(a,x)
 ip(a)
def tab(doc,a,rows):
 t=doc.add_table(rows=1,cols=4); t.style="Table Grid"
 for i,x in enumerate(["งานวิจัย/มาตรฐาน","ประเด็นที่ใช้","การเชื่อมโยงกับ AUTOSHEET","ส่วนของรายงาน"]):
  t.rows[0].cells[i].text=x
  for r in t.rows[0].cells[i].paragraphs[0].runs:r.bold=True
 for row in rows:
  c=t.add_row().cells
  for i,x in enumerate(row):c[i].text=x
 a._p.addprevious(t._tbl)
def main():
 doc=Document(DOC)
 c2,c3=fp(doc,"บทที่ 2"),fp(doc,"บทที่ 3"); db(c2,c3); ip(c3,"หลักการ ทฤษฎี และงานวิจัยที่เกี่ยวข้อง",bold=True,center=True)
 for h,ps in D["CH2"]:sec(c3,h,ps)
 ip(c3,"2.8.1 Literature Matrix เบื้องต้น","Heading 2"); ip(c3,"ตาราง 2.1 Literature Matrix เบื้องต้น"); tab(doc,c3,D["MATRIX"]); ip(c3)
 if not any("เพื่อรักษาความลับของสถานประกอบการและโครงการ" in p.text for p in doc.paragraphs):
  try:
   h=fp(doc,"4.7 ตัวอย่าง Before / After"); p=OxmlElement("w:p"); h._p.addnext(p); r=OxmlElement("w:r"); tt=OxmlElement("w:t"); tt.text=D["CONF_NOTE"]; r.append(tt); p.append(r)
  except:pass
 c5,refs=fp(doc,"บทที่ 5"),fp(doc,"เอกสารอ้างอิง"); db(c5,refs); ip(refs,"สรุป อภิปรายผล และข้อเสนอแนะ",bold=True,center=True)
 for h,ps in D["CH5"]:sec(refs,h,ps)
 app=fp(doc,"ภาคผนวก"); db(refs,app)
 for x in D["REFS"]:ip(app,x)
 ip(app); doc.save(DOC); print("updated",DOC)
if __name__=="__main__":main()